{
  "name": "app",
  "type": "module",
  "workspaces": [".wasp/out/*", ".wasp/out/sdk/wasp"],
  "dependencies": {
    "react": "^19.2.1",
    "react-dom": "^19.2.1",
    "react-router": "^7.12.0"
  },
  "devDependencies": {
    "@types/node": "^24.0.0",
    "@types/react": "^19.2.7",
    "@types/react-dom": "^19.2.3",
    "prisma": "5.19.1",
    "typescript": "5.9.3",
    "vite": "^7.0.6",
    "vitest": "^4.0.16",
    "@wasp.sh/spec": "file:.wasp/spec/"
  }
}

import { app, page, route } from "@wasp.sh/spec";
import { MainPage } from "./src/MainPage" with { type: "ref" };

export default app({
  name: "app",
  title: "app",
  wasp: { version: "^0.24.0" },
  head: ["<link rel='icon' href='/favicon.ico' />"],
  spec: [
    route("RootRoute", "/", page(MainPage)),
  ],
});

datasource db {
  provider = "sqlite"
  // Wasp requires that the url is set to the DATABASE_URL environment variable.
  url      = env("DATABASE_URL")
}

// Wasp requires the `prisma-client-js` generator to be present.
generator client {
  provider = "prisma-client-js"
}

* {
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family:
    -apple-system, BlinkMacSystemFont, "Segoe UI", "Roboto", "Oxygen", "Ubuntu",
    "Cantarell", "Fira Sans", "Droid Sans", "Helvetica Neue", sans-serif;
}

#root {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
}

.container {
  margin: 3rem 3rem 10rem 3rem;
  max-width: 726px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  text-align: center;
}

.logo {
  max-height: 200px;
  margin-bottom: 1rem;
}

.title {
  font-size: 4rem;
  font-weight: 700;
  margin-bottom: 1rem;
}

.content {
  font-size: 1.2rem;
  font-weight: 400;
  line-height: 2;
  margin-bottom: 3rem;
}

.buttons {
  display: flex;
  flex-direction: row;
  gap: 1rem;
}

.button {
  font-size: 1.2rem;
  font-weight: 700;
  text-decoration: none;
  padding: 1.2rem 1.5rem;
  border-radius: 10px;
}

.button-filled {
  color: black;
  background-color: #ffcc00;
  border: 2px solid #ffcc00;

  transition: all 0.2s ease-in-out;
}

.button-filled:hover {
  filter: brightness(0.95);
}

.button-outlined {
  color: black;
  background-color: transparent;
  border: 2px solid #ffcc00;

  transition: all 0.2s ease-in-out;
}

.button-outlined:hover {
  filter: brightness(0.95);
}

code {
  border-radius: 5px;
  border: 1px solid #ffcc00;
  padding: 0.2rem;
  background: #ffcc0044;
  font-family:
    Menlo,
    Monaco,
    Lucida Console,
    Liberation Mono,
    DejaVu Sans Mono,
    Bitstream Vera Sans Mono,
    Courier New,
    monospace;
}

{
  "files": [],
  "references": [
    { "path": "./tsconfig.src.json" },
    { "path": "./tsconfig.wasp.json" }
  ]
}

{
  "name": "@wasp.sh/spec",
  "version": "0.24.0",
  "type": "module",
  "description": "Wasp TS SDK",
  "author": "wasp",
  "license": "MIT",
  "bin": {
    "__internal_wasp_spec__": "./dist/src/run.js"
  },
  "exports": {
    ".": {
      "types": "./dist/src/index.d.ts",
      "default": "./dist/src/index.js"
    },
    "./internal": {
      "types": "./dist/src/internal.d.ts",
      "default": "./dist/src/internal.js"
    }
  },
  "scripts": {
    "build": "tsc",
    "coverage": "vitest run --coverage",
    "dev": "nodemon ./src/index.ts",
    "test": "npm run build && vitest run --reporter=verbose",
    "test:integration": "npm run build && vitest run --reporter=verbose --project integration",
    "test:type": "npm run build && vitest run --reporter=verbose --project type",
    "test:unit": "npm run build && vitest run --reporter=verbose --project unit",
    "test:watch": "npm run build && vitest --reporter=verbose"
  },
  "dependencies": {
    "estree-util-scope": "^1.0.0",
    "estree-walker": "^3.0.3",
    "type-fest": "^5.6.0",
    "typescript": "^5.8.3",
    "unrun": "^0.3.0"
  },
  "devDependencies": {
    "@eslint/js": "^9.9.0",
    "@types/node": "^22.17.0",
    "@vitest/coverage-v8": "^4.0.16",
    "eslint": "^9.9.0",
    "globals": "^15.9.0",
    "nodemon": "^3.1.4",
    "typescript-eslint": "^8.1.0",
    "vitest": "^4.0.16"
  }
}

